// 辞任申请不消耗公私财产；批准只调用原Office失效writer，拒绝/撤回没有职位副作用。
#include "political_office_resignation_detail.hpp"
namespace hanmo::resident {namespace {
using namespace office_resignation_detail;
bool same_authority(const ActingAuthority& a,const ActingAuthority& b){return std::tie(a.organization_id,a.office_id,a.actor_id,a.authority_epoch)==std::tie(b.organization_id,b.office_id,b.actor_id,b.authority_epoch);}
bool same(const PoliticalOfficeResignationCommand& a,const PoliticalOfficeResignationCommand& b){if(a.index()!=b.index())return false;return std::visit([&](const auto& v){using T=std::decay_t<decltype(v)>;const auto& z=std::get<T>(b);if constexpr(std::is_same_v<T,PoliticalRequestOfficeResignation>)return std::tie(v.policy_id,v.expected_office_epoch,v.expected_jurisdiction_revision)==std::tie(z.policy_id,z.expected_office_epoch,z.expected_jurisdiction_revision);else if constexpr(std::is_same_v<T,PoliticalAnswerOfficeResignation>)return same_authority(v.authority,z.authority)&&std::tie(v.request_fact_id,v.accept)==std::tie(z.request_fact_id,z.accept);else return v.request_fact_id==z.request_fact_id;},a);}
}
Outcome<PoliticalOfficeResignationQuote> preview_political_office_resignation(const PoliticalOfficeResignationContext& x,const StableId& actor,const PoliticalOfficeResignationCommand& command){
 auto fail=[](const Status& s)->Outcome<PoliticalOfficeResignationQuote>{return {false,{},s.error};};if(x.authored_command){if(!x.responses||x.state.version!=2)return fail(common_failure("OfficeResignationResponseVersionPairRequired"));auto allowed=validate_political_office_resignation_authored_command(x.common,x.organizations,x.organization_catalog,x.state,*x.responses,*x.authored_command,actor,command);if(!allowed.ok)return fail(allowed);}else if(actor!=x.common.state().metadata.player_actor_id)return fail(common_failure("PoliticalOfficeResignationPlayerRequired"));auto valid=validate_political_office_resignation_sources(x);if(!valid.ok)return fail(valid);if(x.state.requests.size()+x.state.answers.size()+x.state.withdrawals.size()>=4096)return fail(common_failure("PoliticalOfficeResignationHistoryCapacity"));
 valid=std::visit([&](const auto& cmd)->Status{using T=std::decay_t<decltype(cmd)>;
  if constexpr(std::is_same_v<T,PoliticalRequestOfficeResignation>){const auto* p=x.catalog.policies.find(cmd.policy_id);const auto* j=p?x.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;const auto* head=p?x.successions.policies.find(p->approval_succession_policy_id):nullptr;const auto* approver=head?x.organizations.offices.find(head->leader_office_id):nullptr;if(!p||!j||!head||!approver||!approver->holder_actor_id||*approver->holder_actor_id==actor)return common_failure("PoliticalOfficeResignationApproverRequired");if(x.common.tick()<0||x.common.tick()>2147483647-p->response_ticks)return common_failure("PoliticalOfficeResignationDeadlineOverflow");auto v=current_jurisdiction(x,*p,cmd.expected_jurisdiction_revision);if(!v.ok)return v;v=holder_now(x,j->office_id,actor,cmd.expected_office_epoch);if(!v.ok)return v;v=holder_now(x,head->leader_office_id,*approver->holder_actor_id,approver->epoch);if(!v.ok)return v;v=grant(x,*p,x.common.tick());if(!v.ok)return v;for(const auto& who:{actor,*approver->holder_actor_id}){v=contact(x,who,head->seat_place_id);if(!v.ok)return v;}for(const auto& row:x.state.requests.rows()){const auto& old=row.second;if(old.office_id==j->office_id&&old.office_epoch==cmd.expected_office_epoch&&!closed(x.state,old.id)&&x.common.tick()<old.response_until)return common_failure("PoliticalOfficeResignationAlreadyPending",old.id);}return common_success();
  }else{const auto* r=x.state.requests.find(cmd.request_fact_id);if(!r)return common_failure("PoliticalOfficeResignationNotKnown");if constexpr(std::is_same_v<T,PoliticalWithdrawOfficeResignation>){if(actor!=r->actor_id)return common_failure("PoliticalOfficeResignationNotKnown");}else if(actor!=r->approver_actor_id)return common_failure("PoliticalOfficeResignationNotKnown");if(closed(x.state,r->id)||x.common.tick()>=r->response_until)return common_failure("PoliticalOfficeResignationClosed",r->id);const auto& p=*x.catalog.policies.find(r->policy_id);const auto& j=*x.politics_catalog.jurisdictions.find(p.jurisdiction_id);const auto& head=*x.successions.policies.find(p.approval_succession_policy_id);
   if constexpr(std::is_same_v<T,PoliticalWithdrawOfficeResignation>){if(actor!=r->actor_id)return common_failure("PoliticalOfficeResignationNotKnown");return contact(x,actor,head.seat_place_id);}
   else {if(actor!=r->approver_actor_id||!same_authority(cmd.authority,{r->organization_id,r->approver_office_id,r->approver_epoch,r->approver_actor_id}))return common_failure("PoliticalOfficeResignationApproverChanged",r->id);auto v=current_jurisdiction(x,p,r->jurisdiction_revision);if(!v.ok)return v;v=holder_now(x,r->office_id,r->actor_id,r->office_epoch);if(!v.ok)return v;v=holder_now(x,r->approver_office_id,actor,r->approver_epoch);if(!v.ok)return v;v=grant(x,p,x.common.tick());if(!v.ok)return v;auto proof=check_authority(x.common,x.organizations,x.organization_catalog,cmd.authority,political_office_resignation_answer_command,{ScopeRef::Kind::site,head.seat_place_id},0);if(!proof.ok)return {false,{},proof.error};for(const auto& who:{actor,r->actor_id}){v=contact(x,who,head.seat_place_id);if(!v.ok)return v;}if(cmd.accept&&r->office_epoch==std::numeric_limits<Integer>::max())return common_failure("AuthorityEpochOverflow",r->office_id);return common_success();}
  }
 },command);return valid.ok?Outcome<PoliticalOfficeResignationQuote>{true,{x.common.state().identity,actor,command},{}}:fail(valid);
}
Outcome<StableId> apply_political_office_resignation_in_candidate(CommonStore& common,OrganizationState& organizations,PoliticalOfficeResignationState& state,const PoliticalOfficeResignationContext& x,const StableId& actor,const PoliticalOfficeResignationCommand& command,const PoliticalOfficeResignationQuote& quote){
 const auto& a=common.state().identity;const auto& b=quote.identity;if(&common!=&x.common||&organizations!=&x.organizations||&state!=&x.state||actor!=quote.actor_id||!same(command,quote.command)||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick))return {false,{},common_failure("StalePoliticalOfficeResignationQuote").error};auto ready=preview_political_office_resignation(x,actor,command);if(!ready.ok)return {false,{},ready.error};auto next=state;auto offices=organizations;
 auto result=std::visit([&](const auto& cmd)->Outcome<StableId>{using T=std::decay_t<decltype(cmd)>;StableId prefix,kind;if constexpr(std::is_same_v<T,PoliticalRequestOfficeResignation>){prefix="political_office_resignation_request";kind="political_office_resignation_requested";}else if constexpr(std::is_same_v<T,PoliticalAnswerOfficeResignation>){prefix="political_office_resignation_answer";kind="political_office_resignation_answered";}else{prefix="political_office_resignation_withdrawal";kind="political_office_resignation_withdrawn";}auto id=common.next_id(prefix);if(!id.ok)return id;auto valid=common.append_fact({id.value,kind,political_office_resignation_module});if(!valid.ok)return {false,{},valid.error};bool inserted=false;
  if constexpr(std::is_same_v<T,PoliticalRequestOfficeResignation>){const auto& p=*x.catalog.policies.find(cmd.policy_id);const auto& j=*x.politics_catalog.jurisdictions.find(p.jurisdiction_id);const auto& head=*x.successions.policies.find(p.approval_succession_policy_id);const auto& approver=*offices.offices.find(head.leader_office_id);PoliticalOfficeResignationRequest row{id.value,p.id,j.political_organization_id,j.office_id,actor,head.leader_office_id,*approver.holder_actor_id,cmd.expected_office_epoch,approver.epoch,cmd.expected_jurisdiction_revision,common.tick(),common.tick()+p.response_ticks,{}};inserted=next.requests.insert(id.value,std::move(row));}
  else if constexpr(std::is_same_v<T,PoliticalAnswerOfficeResignation>){const auto& r=*next.requests.find(cmd.request_fact_id);const auto& p=*x.catalog.policies.find(r.policy_id);PoliticalOfficeResignationAnswer row{id.value,r.id,actor,p.approval_grant_id,{},r.approver_epoch,0,common.tick(),cmd.accept,{}};if(cmd.accept){const auto before=offices.facts.size();valid=invalidate_office(common,offices,x.organization_catalog,r.office_id,common.tick(),id.value);if(!valid.ok)return {false,{},valid.error};const auto* office=offices.offices.find(r.office_id);if(offices.facts.size()!=before+1||office->holder_actor_id||office->epoch!=r.office_epoch+1)return {false,{},common_failure("PoliticalOfficeResignationActualVacancyRequired").error};row.office_change_fact_id=offices.facts.rows().back().first;row.vacant_office_epoch=office->epoch;}inserted=next.answers.insert(id.value,std::move(row));}
  else inserted=next.withdrawals.insert(id.value,{id.value,cmd.request_fact_id,actor,common.tick(),{}});
  return inserted?id:Outcome<StableId>{false,{},common_failure("DuplicatePoliticalOfficeResignationFact",id.value).error};
 },command);if(!result.ok)return result;if(x.authored_command&&!next.authored_origins.insert(result.value,*x.authored_command))return {false,{},common_failure("OfficeResignationResponseDuplicateOrigin",result.value).error};organizations=std::move(offices);state=std::move(next);return result;
}
}
